// And groups predicates with the AND operator between them.
func And(predicates ...predicate.StudentEnrollment) predicate.StudentEnrollment {
	return predicate.StudentEnrollment(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.StudentEnrollment) predicate.StudentEnrollment {
	return predicate.StudentEnrollment(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.StudentEnrollment) predicate.StudentEnrollment {
	return predicate.StudentEnrollment(sql.NotPredicates(p))
}
